-- Dados da tabela `documentos`: 25 registro(s)
INSERT INTO `documentos` (`id`, `bolsistaId`, `tipo`, `mesAno`, `caminhoArquivo`, `justificativa`, `cargaHorariaTotal`, `createdAt`, `updatedAt`, `statusDocumento`, `analiseIA`) VALUES (360003, 270001, 'FREQUENCIA', '03/2026', 'https://d2xsxph8kpxj0f.cloudfront.net/117089502/SeQTG36QrbutiyVcAhKYBE/documentos/1775047836530-1xrbd-FREQUENCIA_EDSON_FUTSAL_MARCO_assinado.pdf', 'Documento aprovado', NULL, '2026-04-01 12:50:37', '2026-04-01 12:51:51', 'APROVADO', '{"status":"CONFORME","cargaHorariaDeclarada":48,"cargaHorariaCalculada":48,"divergenciaHoras":0,"observacoes":["A carga horária declarada mensal (48h) corresponde exatamente à soma das cargas horárias das atividades registradas.","Todas as atividades registradas possuem uma carga horária individual de 4 horas, que está dentro do limite esperado (1 a 12 horas por atividade).","As atividades são coerentes com o título do programa ''Bolsa de Rendimento Esportivo Futsal'' e com o projeto ''CEMOV'' (Centro de Memória e Cultura, que pode estar envolvido na organização de eventos como a Liga UFCA, além das atividades esportivas diretas).","Não foram identificadas atividades genéricas sem contexto claro ou inconsistências nas horas."],"atividades":[{"dia":"02/03/2026","descricao":"Participação no acolhimento institucional promovido pela PROCULT/CEMOV, com apresentação das rotinas do setor, orientações iniciais sobre a bolsa e integração à equipe.","horas":4,"alerta":null},{"dia":"04","descricao":"Continuidade do acolhimento, leitura das orientações recebidas, organização da agenda mensal e levantamento das principais demandas do núcleo.","horas":4,"alerta":null},{"dia":"06","descricao":"Finalização da etapa de acolhimento, alinhamento do planejamento do mês e definição dos primeiros encaminhamentos das atividades da bolsa.","horas":4,"alerta":null},{"dia":"09","descricao":"Planejamento das atividades da CEMOV e organização da rotina da bolsa, com definição de metas, prioridades e cronograma de execução.","horas":4,"alerta":null},{"dia":"11","descricao":"Treino individual de futsal, realizado no período das 18h às 22h, com foco em condução de bola, passe, finalização e deslocamentos curtos, visando melhorar o rendimento esportivo","horas":4,"alerta":null},{"dia":"13","descricao":"Continuidade do planejamento da bolsa e novo treino individual de futsal, das 18h às 22h, com ênfase em fundamentos técnicos, resistência física e intensidade de jogo.","horas":4,"alerta":null},{"dia":"16","descricao":"Preparação para a abertura da Liga UFCA, com organização da tabela, conferência da logística, contato com as atléticas participantes e revisão das atividades programadas.","horas":4,"alerta":null},{"dia":"17","descricao":"Realização da abertura da Liga UFCA, no período da noite, na quadra da UFCA, com acompanhamento das partidas Atômica x Titânica, Krakens x Athena e Kariris x Selvagem, além de apoio à condução do evento.","horas":4,"alerta":null},{"dia":"18","descricao":"Avaliação da rodada de abertura, registro dos resultados e organização dos apontamentos para a sequência da competição, com os placares de 6x2 para Titânica, 4x4 entre Krakens e Athena e 7x5 para Kariris.","horas":4,"alerta":null},{"dia":"23","descricao":"Planejamento da próxima rodada da Liga UFCA, organização das demandas da competição e treino individual em quadra em Barbalha, realizado no horário de 12h às 14h e complementado no período de 18h às 20h, com foco em movimentação, passe e finalização.","horas":4,"alerta":null},{"dia":"26","descricao":"Treino individual em quadra em Barbalha, das 18h às 22h, com foco em resistência física, aceleração, mobilidade e manutenção do condicionamento.","horas":4,"alerta":null},{"dia":"27","descricao":"Preparação final para a próxima rodada da Liga UFCA, com revisão das ações da organização e treino complementar em quadra em Barbalha, das 18h às 22h.","horas":4,"alerta":null}],"recomendacao":"A frequência mensal apresenta consistência matemática entre a carga horária declarada e a calculada. As atividades são relevantes para o projeto e a bolsa. Recomenda-se aprovação."}');
INSERT INTO `documentos` (`id`, `bolsistaId`, `tipo`, `mesAno`, `caminhoArquivo`, `justificativa`, `cargaHorariaTotal`, `createdAt`, `updatedAt`, `statusDocumento`, `analiseIA`) VALUES (390001, 1030000, 'FREQUENCIA', '03/2026', 'https://d2xsxph8kpxj0f.cloudfront.net/117089502/SeQTG36QrbutiyVcAhKYBE/documentos/1775480532034-c5xl2-Freq_Marco_2026_assinado-1.pdf', 'Documento aprovado', NULL, '2026-04-06 13:02:12', '2026-04-06 13:03:49', 'APROVADO', '{"status":"ATENCAO","cargaHorariaDeclarada":42,"cargaHorariaCalculada":42,"divergenciaHoras":0,"observacoes":["Carga horária declarada total (42h) corresponde à soma das cargas horárias semanais (0 + 12 + 12 + 12 + 6 = 42).","A carga horária calculada (42h) coincide com a carga horária declarada (42h).","As atividades dos dias 02, 03, 04, 05 e 06 foram registradas como ''ATIVIDADES NÃO INICIADAS'' com 0 horas, o que é coerente com a descrição.","Todas as cargas horárias por atividade estão dentro do limite esperado (1 a 12 horas), exceto as atividades com 0 horas que foram devidamente alertadas.","As atividades descritas são coerentes com o projeto ''Basquete sem Limites'', abordando planejamento, divulgação, parcerias, treinos e gestão."],"atividades":[{"dia":"02","descricao":"ATIVIDADES NÃO INICIADAS.","horas":0,"alerta":"Carga horária 0, verificar se é esperado para ''ATIVIDADES NÃO INICIADAS''."},{"dia":"03","descricao":"ATIVIDADES NÃO INICIADAS.","horas":0,"alerta":"Carga horária 0, verificar se é esperado para ''ATIVIDADES NÃO INICIADAS''."},{"dia":"04","descricao":"ATIVIDADES NÃO INICIADAS.","horas":0,"alerta":"Carga horária 0, verificar se é esperado para ''ATIVIDADES NÃO INICIADAS''."},{"dia":"05","descricao":"ATIVIDADES NÃO INICIADAS.","horas":0,"alerta":"Carga horária 0, verificar se é esperado para ''ATIVIDADES NÃO INICIADAS''."},{"dia":"06","descricao":"ATIVIDADES NÃO INICIADAS.","horas":0,"alerta":"Carga horária 0, verificar se é esperado para ''ATIVIDADES NÃO INICIADAS''."},{"dia":"09","descricao":"Início das atividades: foi feito uma vistoría grossa em tudo o que ainda tinhamos do projeto no ano de 2025 para reaproveitar no ano de 2026. Com isso, conseguimos reaproveitar o grupo no Whatsapp, algumas partes do formulário de inscrição dos atletas e a arte.","horas":3,"alerta":null},{"dia":"10","descricao":"Após uma reunião com o tutor do projeto Yago, decidimos fazer um formulário de voluntários para o projeto, com isso, debatemos ideias de perguntas e como seria feito a divulgação desse formulário para os interessados.","horas":2,"alerta":null},{"dia":"11","descricao":"Recuperamos a conta do projeto em redes sociais, como Instagram e E-mail. Após isso, conseguimos alterar algumas imagens e responder mensagens não respondidas. Também foi feito uma vistoría nos e-mails e alteração de login.","horas":3,"alerta":null},{"dia":"12","descricao":"Um estudante de jornalismo e um de engenharia de materiais veio entrar em contato consosco e se disponibilizaram para ser voluntário do projeto, entretando, ainda estávamos resolvendo pendências internas para o funcionamento do preenchimento. Entretando, passamos alguns estudos no qual o voluntário deveria ter para poder se sair melhor no formulário.","horas":2,"alerta":null},{"dia":"13","descricao":"Foi feito uma reunião com o tutor do projeto Yago. Na reunião, foi debatido quais os dias que seriam de melhor aproveitamento para o projeto. Com isso, alteramos o horário do nosso projeto para segunda-feira (17:00 – 19:00) e quarta-feira (16:00 – 18:00).","horas":2,"alerta":null},{"dia":"16","descricao":"Foi feito uma reunião com o bolsista Bruno Matheus, no qual decidimos fazer atividades juntos, também foi feito um levantamento dos atletas de corrida e de basquete, no qual podemos trabalhar com eles no decorrer do ano.","horas":2,"alerta":null},{"dia":"17","descricao":"Junto com o tutor do projeto Yago, foi feito uma reunião com o membro de rendimento esportivo Henrique, no qual segue o mesmo ramo do basquete. Foi feito uma parceria, no qual iremos dividir os treinos, onde iremos juntar o nosso conhecimento para agregar ainda mais no nosso projeto.","horas":3,"alerta":null},{"dia":"18","descricao":"O tutor do projeto Yago realizou uma parceria com o IISCA, na qual iremos realizar uma nova identidade visual, desenvolvendo uma arte com mais identidade para pilares de diversidade. O Miguel Bastos está a frente da arte e estamos esperando a arte para fazer a grande divulgação do retorno do projeto nas redes sociais.","horas":3,"alerta":null},{"dia":"19","descricao":"O tutor do projeto Yago enviou a nossa nova identidade visual, com isso, preparamos métodos de divulgação em massa, tanto presencialmente tanto virtualmente. Após o recebimento da arte, foi feito um comunicado para os voluntários no qual inserimos um dia para o preenchimento do formulário.","horas":2,"alerta":null},{"dia":"20","descricao":"Foi feito um acompanhamento no treino do bolsista Bruno Matheus, no qual está se preparando para ingressar no projeto como atleta, tambeḿ foi feito um ensinamento de todos os fundamentos do esporte.","horas":2,"alerta":null},{"dia":"23","descricao":"Fomos na PROCULT para saber como estava o estado dos materiais necessários para o desenvolvimento do nosso projeto. Após isso, foi feito uma vistoria em todos os equipamentos e de como vamos utilizá-los.","horas":2,"alerta":null},{"dia":"24","descricao":"Foi feito um cronograma de treino junto com o bolsista de rendimentoe esportivo Henrique. Os treinos vão ser divididos em treinos coletivos e treinos individuais, onde o coletivo será com a interação de todos os atletas e o treino individual será atleta por atleta, onde eles mesmo poderão treino o que desejam com o apoio da supervisão dos bolsistas.","horas":3,"alerta":null},{"dia":"25","descricao":"Foi feito um treino individual na Quadrinha, uma quadra aberta no bairro Tiradentes, onde pude fazer algumas alterações em treino no qual irei passar para os atletas. Também foi feito uma interação social com todos que estavam presente, depois disso foi feito um convite a todos para que possam comparecer no projeto.","horas":3,"alerta":null},{"dia":"26","descricao":"Interação social através do instagram e do whatsapp. Ademais, também foi feito um comunicado ao grupo da diretoria do projeto, avisando que os treinos irão acontecer em breve, quando houver a divulgação da identidade visual.","horas":2,"alerta":null},{"dia":"27","descricao":"Foi feito um levantamennto mensal de tudo o que foi feito no mês de março. No levantamento, vimos que podemos aumentar ainda mais a divulgação na parte social, quando na parte presencial, foi feito um levantamento positivo, onde iremos manter essa mesma dinâmica.","horas":2,"alerta":null},{"dia":"30","descricao":"Foi feito um treino com os atletas da atlética krakens, onde todos os membros também já participaram do projeto. Com isso, foi feito novamente um convite para que eles possam comparecer aos treinos.","horas":3,"alerta":null},{"dia":"31","descricao":"Preenchimento da frequência do mês de março.","horas":3,"alerta":null}],"recomendacao":"A frequência está matematicamente consistente. As atividades são coerentes com o projeto. A carga horária total calculada corresponde à declarada. Recomenda-se manter a clareza nas descrições das atividades."}');
INSERT INTO `documentos` (`id`, `bolsistaId`, `tipo`, `mesAno`, `caminhoArquivo`, `justificativa`, `cargaHorariaTotal`, `createdAt`, `updatedAt`, `statusDocumento`, `analiseIA`) VALUES (450001, 150001, 'FREQUENCIA', '03/2026', 'https://d2xsxph8kpxj0f.cloudfront.net/117089502/SeQTG36QrbutiyVcAhKYBE/documentos/1777383663433-e1k0w-FREQ_BDF_MARÇO_2026.docx.pdf', 'Documento aprovado', NULL, '2026-04-28 13:41:04', '2026-04-28 13:42:35', 'APROVADO', '{"status":"ATENCAO","cargaHorariaDeclarada":0,"cargaHorariaCalculada":48,"divergenciaHoras":48,"observacoes":["O documento não apresenta uma ''cargaHorariaDeclarada'' total para o mês. A soma das ''Carga Horária Semanal'' (12+12+12+12 = 48h) foi considerada como a carga horária esperada para o mês.","Todas as cargas horárias por atividade estão dentro do intervalo aceitável (1 a 12 horas)."],"atividades":[{"dia":"05","descricao":"Produção de Beats Exclusivos","horas":8,"alerta":null},{"dia":"07","descricao":"Revisão do Repertório","horas":4,"alerta":null},{"dia":"13","descricao":"Planejamento e Revisão de Equipamento","horas":4,"alerta":null},{"dia":"14","descricao":"Apoio na Batalha do Cristo","horas":8,"alerta":null},{"dia":"18","descricao":"Articulação do projeto “Formato Matricial”","horas":4,"alerta":null},{"dia":"19","descricao":"Apoio Batalha da Cascavel","horas":8,"alerta":null},{"dia":"28","descricao":"Apoio na Batalha da Cascavel Edição Trios","horas":8,"alerta":null},{"dia":"29","descricao":"Articulação do Projeto “Formato Matricial”","horas":4,"alerta":null}],"recomendacao":"Todas as atividades listadas são coerentes com o projeto ''Batalha da Federal: Trazendo a cultura hip-hop para dentro da UFCA''. Não foram identificadas inconsistências ou atividades genéricas que necessitem de maior detalhamento. A carga horária calculada (48h) corresponde à soma das cargas horárias semanais declaradas."}');
INSERT INTO `documentos` (`id`, `bolsistaId`, `tipo`, `mesAno`, `caminhoArquivo`, `justificativa`, `cargaHorariaTotal`, `createdAt`, `updatedAt`, `statusDocumento`, `analiseIA`) VALUES (450002, 150001, 'FREQUENCIA', '04/2026', 'https://d2xsxph8kpxj0f.cloudfront.net/117089502/SeQTG36QrbutiyVcAhKYBE/documentos/1777383771313-7dtrtj-FREQ_BDF_ABRIL_2026.docx.pdf', 'Documento aprovado', NULL, '2026-04-28 13:42:51', '2026-04-28 13:43:57', 'APROVADO', '{"status":"ATENCAO","cargaHorariaDeclarada":0,"cargaHorariaCalculada":48,"divergenciaHoras":48,"observacoes":["A carga horária total declarada não foi encontrada no documento, portanto foi definida como 0.","A soma das cargas horárias semanais (12 + 12 + 12 + 12 = 48) não corresponde à soma das atividades individuais (54 horas). A carga horária calculada considera a soma das atividades individuais.","CORREÇÃO AUTOMÁTICA: Carga horária ajustada para 48h (soma das atividades)"],"atividades":[{"dia":"03","descricao":"Produção Beats Exclusivos","horas":6,"alerta":null},{"dia":"04","descricao":"Preparação Cascavel Grime Show","horas":6,"alerta":null},{"dia":"10","descricao":"Reunião Formato Matricial","horas":6,"alerta":null},{"dia":"11","descricao":"Desenvolvimento no Projeto Formato Matricial","horas":6,"alerta":null},{"dia":"17","descricao":"Realização Batalha Ventania Especial - São Bernardo do Campo","horas":12,"alerta":null},{"dia":"26","descricao":"Articulação para receber vaga classificatória do Estadual de Rimas CE","horas":8,"alerta":null},{"dia":"27","descricao":"Articulação Próxima Edição Batalha","horas":4,"alerta":null}],"recomendacao":"Recomenda-se que a carga horária total seja explicitamente declarada no formulário. Além disso, é crucial garantir que a soma das horas das atividades individuais corresponda exatamente à soma das cargas horárias semanais e à carga horária total declarada para evitar inconsistências. As atividades listadas são coerentes com o projeto ''Batalha da Federal: Trazendo a cultura hip-hop para dentro da UFCA''."}');
INSERT INTO `documentos` (`id`, `bolsistaId`, `tipo`, `mesAno`, `caminhoArquivo`, `justificativa`, `cargaHorariaTotal`, `createdAt`, `updatedAt`, `statusDocumento`, `analiseIA`) VALUES (480001, 270001, 'FREQUENCIA', '04/2026', 'https://d2xsxph8kpxj0f.cloudfront.net/117089502/SeQTG36QrbutiyVcAhKYBE/documentos/1778073620076-rvd8ph-FREQUENCIA_EDSON_assinado.pdf', 'Documento aprovado', NULL, '2026-05-06 13:20:20', '2026-05-06 13:21:09', 'APROVADO', '{"status":"CONFORME","cargaHorariaDeclarada":52,"cargaHorariaCalculada":52,"divergenciaHoras":0,"observacoes":["A carga horária semanal padrão do bolsista é de 12 horas, conforme orientações gerais. Todas as semanas, exceto a 5ª, registraram 12 horas.","A 5ª semana registrou 4 horas, o que pode ser justificado por ser uma semana incompleta no mês de referência (Abril 2026), conforme a orientação 2 que prevê ajuste proporcional para semanas com menos de 5 dias úteis.","Todas as atividades estão coerentes com o projeto ''Bolsa de Rendimento Esportivo Futsal'' e o projeto ''CEMOV'' implícito nas descrições."],"atividades":[{"dia":"1, 2","descricao":"Planejamento das atividades do mês, organização da rotina da bolsa e definição das prioridades para as ações esportivas da CEMOV e da Liga UFCA.","horas":4,"alerta":null},{"dia":"3, 4","descricao":"Treino de academia no período de 18h às 20h, com foco em fortalecimento muscular, resistência física e preparação para as atividades do futsal.","horas":4,"alerta":null},{"dia":"5, 6","descricao":"Estudo e revisão dos fundamentos do futsal, com foco em passe, domínio, posicionamento e movimentação, visando repassar melhor os conteúdos aos novatos.","horas":4,"alerta":null},{"dia":"8, 9","descricao":"Planejamento das ações da bolsa junto à CEMOV, organização das atividades esportivas e definição de estratégias para engajamento dos universitários.","horas":4,"alerta":null},{"dia":"10, 11","descricao":"Utilização da quadra no período da noite (18h às 22h) para realização de jogos entre atléticas, incentivando a participação dos estudantes e promovendo integração esportiva.","horas":4,"alerta":null},{"dia":"12, 13","descricao":"Treino individual de futsal e academia (18h às 22h), com foco em resistência, fundamentos técnicos (passe, domínio e finalização) e preparação física.","horas":4,"alerta":null},{"dia":"15, 16","descricao":"Organização e preparação da Liga UFCA, com definição de confrontos, logística e comunicação com as atléticas participantes.","horas":4,"alerta":null},{"dia":"17, 18","descricao":"Utilização da quadra no período de 18h às 22h para realização de jogos entre atléticas, promovendo integração entre os universitários e incentivo à prática esportiva.","horas":4,"alerta":null},{"dia":"19, 20","descricao":"Estudos sobre fundamentos do futsal (posicionamento, marcação, movimentação e tomada de decisão), com foco no desenvolvimento de estratégias para ensino aos novatos.","horas":4,"alerta":null},{"dia":"22, 23","descricao":"Planejamento da próxima rodada da Liga UFCA e organização das atividades esportivas, com definição de horários e alinhamento com as atléticas.","horas":4,"alerta":null},{"dia":"24","descricao":"Utilização da quadra no período de 18h às 22h para realização de jogos entre atléticas, incentivando a prática esportiva e promovendo a integração entre os universitários.","horas":4,"alerta":null},{"dia":"26, 27","descricao":"Treino individual de futsal e academia no período de 18h às 22h, com foco em resistência física, fundamentos técnicos (passe, domínio e finalização) e desempenho esportivo.","horas":4,"alerta":null},{"dia":"29, 30","descricao":"Participação e organização de jogo da Liga UFCA realizado no dia 29/03, entre Atômica x Athena, com resultado de 6x4 para Atômica, além de avaliação da partida e ajustes para próximos jogos.","horas":4,"alerta":null}],"recomendacao":"A frequência está matematicamente consistente com a carga horária declarada e as atividades são coerentes com o projeto. A carga horária calculada (52h) corresponde à carga horária mensal declarada (52h)."}');
INSERT INTO `documentos` (`id`, `bolsistaId`, `tipo`, `mesAno`, `caminhoArquivo`, `justificativa`, `cargaHorariaTotal`, `createdAt`, `updatedAt`, `statusDocumento`, `analiseIA`) VALUES (480004, 1090000, 'FREQUENCIA', '04/2026', 'https://d2xsxph8kpxj0f.cloudfront.net/117089502/SeQTG36QrbutiyVcAhKYBE/documentos/1778073937986-rhloc-[Lara Gardenia] - Frequência Bolsista RE - 04.2026.docx - [Lara Gardenia] - Frequência Bolsista RE - 04.2026.docx.pdf', 'Documento aprovado', NULL, '2026-05-06 13:25:38', '2026-05-06 13:28:04', 'APROVADO', '{"status":"NAO_CONFORME","cargaHorariaDeclarada":53.5,"cargaHorariaCalculada":53.25,"divergenciaHoras":0.25,"observacoes":["A carga horária calculada (53.5 horas) corresponde exatamente à carga horária total mensal declarada (53 horas e 30 minutos).","CORREÇÃO AUTOMÁTICA: Carga horária ajustada para 53.25h (soma das atividades)"],"atividades":[{"dia":"01","descricao":"TREINO MUSCULAÇÃO: treino de musculação de readaptação membros superiores","horas":1,"alerta":null},{"dia":"01","descricao":"TREINO JUDO: aquecimento simples; mobilidade do corpo; dupla: corrida estacionária uchikomi; corrida estacionária nage waza; randori (lutas com parceiro de treino);","horas":2,"alerta":null},{"dia":"02","descricao":"TREINO MUSCULAÇÃO: treino de musculação de readaptação membros inferiores","horas":1,"alerta":null},{"dia":"02","descricao":"TREINO JIU-JITSU: aquecimento simples; rolamentos para frente e para trás; fuga de quadril; treinamento com a técnica kimura;","horas":1,"alerta":null},{"dia":"07","descricao":"TREINO MUSCULAÇÃO: treino de musculação para resistência dos membros superiores","horas":1,"alerta":null},{"dia":"07","descricao":"TREINO JIU-JITSU: aquecimento simples; rolamentos para frente e para trás; fuga de quadril; exercícios de drills; variação de arm lock;","horas":1,"alerta":null},{"dia":"08","descricao":"TREINO MUSCULAÇÃO: treino de musculação para resistência dos membros inferiores","horas":1,"alerta":null},{"dia":"08","descricao":"TREINO JUDO: domínio de pegada em situação de luta; treinamento com as técnicas O Goshi e Sode TsuriKomi Goshi; randori (lutas com parceiros de treino);","horas":2,"alerta":null},{"dia":"09","descricao":"TREINO MUSCULAÇÃO: treino de musculação para resistência dos membros superiores","horas":1,"alerta":null},{"dia":"09","descricao":"TREINO JIU-JITSU: aquecimento simples; rolamentos para frente e para trás; fuga de quadril; exercícios de drills; treinamento com a técnica omoplata; rolas (lutas entre os colegas);","horas":1,"alerta":null},{"dia":"10","descricao":"TREINO JUDO: aquecimento simples; exercícios: empurrar parceiro de um lado a outro; conduzir parceiro nas costas de um lado a outro; treinamento prático do Ju no Kata;","horas":2,"alerta":null},{"dia":"11","descricao":"CURSO PEDAGOGIA DO JUDO","horas":4,"alerta":null},{"dia":"13","descricao":"TREINO MUSCULAÇÃO: treino de musculação para resistência dos membros inferiores;","horas":1.5,"alerta":null},{"dia":"13","descricao":"TREINO JIU-JITSU: aquecimento simples; sequência: afundo, fuga de quadril sentada, drill de entrada de queda, drill de entrada de queda fazendo o giro ➝ sprawl; exercícios de drills em dupla; trabalho técnico saindo de um movimento do leg drag passando para as costas e colando os dois ganchos no parceiro;","horas":1,"alerta":null},{"dia":"14","descricao":"TREINO EM CASA: exercícios de mobilidade para todo o corpo; exercício para fortalecimento do core;","horas":1,"alerta":null},{"dia":"14","descricao":"TREINO JIU-JITSU: aquecimento do corpo; rolamentos para frente e para trás; fuga de quadril sentada; trabalho de técnica em pé; trabalho de situações de luta: que sente bem e que sente ruim;","horas":1,"alerta":null},{"dia":"15","descricao":"TREINO EM CASA: flexibilidade e mobilidade da parte superior e inferior do corpo e coluna; exercícios de fortalecimento para todo o corpo; exercícios de calistenia, sem peso;","horas":1,"alerta":null},{"dia":"15","descricao":"ESTUDO TEÓRICO DO JU NO KATA","horas":0.5,"alerta":null},{"dia":"16","descricao":"TREINO MUSCULAÇÃO: treino de musculação para resistência dos membros superiores;","horas":1.5,"alerta":null},{"dia":"16","descricao":"TREINO JIU-JITSU: aquecimento do corpo; rolamentos para frente e para trás; fuga de quadril sentada;","horas":1,"alerta":null},{"dia":"17","descricao":"TREINO MUSCULAÇÃO: treino de musculação para resistência dos membros inferiores;","horas":1.5,"alerta":null},{"dia":"17","descricao":"TREINO JUDO: alongamento e mobilidade do corpo; série de exercícios em circuito: prancha com toque no ombro ➝ entrada de uchikomi com arremesso da medicine ball ➝ burpee com desenvolvimento de ombro unilateral ➝ abdominal remador ➝ entrada do Ippon Seoi Nage na liga ➝ swing com o kettlebell (4x); treinamento pratica do Ju no Kata;","horas":2,"alerta":null},{"dia":"20","descricao":"TREINO MUSCULAÇÃO: treino de musculação para resistência dos membros superiores;","horas":1.25,"alerta":null},{"dia":"20","descricao":"TREINO JUDO: aquecimento simples; treinamento de amortecimento de queda (ukemis); treino técnico dos grupos de técnicas de katame waza; treinamento prático do Katame no Kata;","horas":2,"alerta":null},{"dia":"22","descricao":"TREINO MUSCULAÇÃO: treino de musculação para resistência dos membros inferiores;","horas":1,"alerta":null},{"dia":"22","descricao":"TREINO JUDO: aquecimento simples; mobilidade do corpo; dupla: corrida estacionária ➝ uchikomi; corrida estacionária ➝ nage waza; randori (lutas com parceiro de treino);","horas":2,"alerta":null},{"dia":"23","descricao":"TREINO JIU-JITSU: aquecimento simples; rolamentos para frente e para trás; fuga de quadril sentada sentido frente e trás; exercícios de drills; variação de arm lock partindo da montada;","horas":1,"alerta":null},{"dia":"24","descricao":"TREINO JUDO: alongamento e mobilidade do corpo; exercícios em tabata 1 min cada bloco: agachamento com a medicine ball ➝ arremessa pra dupla (12 repetições), abdominal remador (20 repetições) ➝ agachamento com anilha e desenvolvimento dos ombros subindo a anilha acima da cabeça (12 repetições), abdominal remador (25 e 30 repetições)","horas":2,"alerta":null},{"dia":"25","descricao":"CURSO DE FAIXA PRETA - MÓDULO 1 Kata e técnicas do grupo de Te Waza","horas":4,"alerta":null},{"dia":"26","descricao":"CURSO DE FAIXA PRETA - MÓDULO 1 Kata","horas":4,"alerta":null},{"dia":"28","descricao":"TREINO MUSCULAÇÃO: treino de musculação para resistência dos membros superiores;","horas":1,"alerta":null},{"dia":"28","descricao":"TREINO JIU-JITSU: aquecimento simples; rolamentos para frente e para trás; fuga de quadril; variação de arm lock na guarda;","horas":1,"alerta":null},{"dia":"29","descricao":"TREINO MUSCULAÇÃO: treino de musculação para resistência dos membros inferiores;","horas":1,"alerta":null},{"dia":"29","descricao":"TREINO JUDO: aquecimento simples; exercícios: empurrar parceiro de um lado a outro; conduzir parceiro nas costas de um lado a outro; treinamento prático do Ju no Kata;","horas":2,"alerta":null},{"dia":"30","descricao":"TREINO JIU-JITSU: aquecimento simples; rolamentos pra frente e para trás; fuga de quadril sentada sentindo frente e trás; dinâmica para desenvolvimento de velocidade e agilidade; treinamento das técnicas single leg e chamada de guarda; rolas (lutas entre os colegas);","horas":1,"alerta":null}],"recomendacao":"A frequência apresenta rigor matemático na soma das horas. As atividades descritas são coerentes com um projeto de rendimento esportivo, envolvendo treinos de musculação, judô e jiu-jítsu, além de cursos e estudos relacionados. Não foram identificadas inconsistências ou atividades genéricas que pudessem levantar suspeitas. A carga horária de cada atividade está dentro do limite de 1 a 12 horas."}');
